# (unité, difficulté, question, choix, index bonne réponse, explication)
Q = [
(0,1,"Qui a écrit la Tuḥfat al-Aṭfāl ?",["Sulaymān al-Jamzūrī","Ibn al-Jazarī","Al-Shāṭibī","Al-Nawawī"],0,"C'est Sulaymān al-Jamzūrī, savant égyptien. Il se nomme lui-même au premier vers."),
(0,1,"De quoi traite le poème, selon le vers 3 ?",["Du nūn, du tanwīn et des madd","Des points de sortie des lettres","Des dix lectures","Des règles de l'arrêt"],0,"Le vers 3 dit : « fi n-nūni wat-tanwīni wal-mudūdi », le nūn, le tanwīn et les prolongations."),
(0,2,"Qui était le maître d'al-Jamzūrī cité au vers 4 ?",["Al-Mīhī","Ibn Kathīr","Al-Dānī","Makkī"],0,"« ʿan shaykhina l-Mīhiyyi » : il a écrit le poème d'après l'enseignement de son maître al-Mīhī."),
(1,1,"Combien de règles ont le nūn sākin et le tanwīn ?",["4","3","2","6"],0,"Vers 6 : « arbaʿu aḥkāmin », quatre règles : iẓhār, idghām, iqlāb et ikhfāʾ."),
(1,1,"Combien de lettres pour l'iẓhār ?",["6","4","15","2"],0,"Les six lettres de la gorge : ء ه ع ح غ خ (vers 7 et 8)."),
(1,1,"Quel mot réunit les lettres de l'idghām ?",["Yarmalūn","Yanmū","Wāy","Ḥayyun ṭāhir"],0,"Vers 9 : « fī yarmalūna » (ي ر م ل و ن). « Yanmū » ne réunit que celles avec ghunna."),
(1,1,"Devant quelles lettres l'idghām se fait-il sans ghunna ?",["ل et ر","ي et و","م et ن","ب et م"],0,"Vers 12 : « fi l-lāmi war-rā », devant le lām et le rāʾ."),
(1,1,"Devant quelle lettre a lieu l'iqlāb ?",["ب","م","و","ق"],0,"Vers 13 : « ʿinda l-bāʾi » : devant le bāʾ, le nūn devient un mīm caché avec ghunna."),
(1,2,"Pourquoi ne fait-on pas d'idghām dans « dunyā » ?",["Le nūn et le yāʾ sont dans le même mot","Le yāʾ n'est pas une lettre d'idghām","On s'arrête sur le mot","C'est un iqlāb"],0,"Vers 11 : pas d'idghām si les deux lettres sont dans le même mot, comme dunyā et ṣinwān. On fait l'iẓhār."),
(1,1,"Combien de lettres pour l'ikhfāʾ ?",["15","14","6","4"],0,"Vers 15 : « fī khamsatin min baʿdi ʿashrin », quinze lettres, cachées au début des mots du vers 16."),
(2,1,"Que fait-on sur un nūn ou un mīm avec chadda ?",["Une ghunna","Un iẓhār","Un madd","Un arrêt"],0,"Vers 17 : « wa ghunna mīman thumma nūnan shuddidā » : chacun est une « lettre de ghunna »."),
(3,1,"Combien de règles a le mīm sākin ?",["3","4","2","6"],0,"Vers 19 : ikhfāʾ, idghām et iẓhār, « faqaṭ » (pas plus)."),
(3,1,"Comment s'appelle l'ikhfāʾ du mīm devant le bāʾ ?",["Ikhfāʾ labial (shafawī)","Ikhfāʾ réel","Iqlāb","Idghām"],0,"Vers 20 : « wa sammihi sh-shafawiyya », on l'appelle labial car le mīm et le bāʾ sortent des lèvres."),
(3,2,"Devant quelles lettres faut-il surtout garder le mīm bien clair ?",["و et ف","ب et م","ل et ر","ء et ه"],0,"Vers 23 : « waḥdhar ladā wāwin wa fā », car ils sortent aussi des lèvres et l'on risque de cacher le mīm."),
(4,1,"Comment s'appelle le lām de « al- » qui se prononce ?",["Lunaire (qamariyya)","Solaire (shamsiyya)","Labial","Lourd"],0,"Vers 28 : le premier lām, prononcé clairement, est appelé « qamariyya »."),
(4,1,"Dans « ash-shams », le lām se…",["fond dans le shīn (solaire)","prononce clairement (lunaire)","change en mīm","cache avec ghunna"],0,"Le shīn fait partie des lettres solaires (vers 27) : le lām ne se prononce pas et le shīn prend une chadda."),
(4,1,"Combien de lettres lunaires ?",["14","15","6","28"],0,"Vers 25 : « qabla rbaʿin maʿ ʿashratin », quatorze lettres réunies dans « ibghi ḥajjaka wa khaf ʿaqīmah »."),
(4,2,"Que fait-on du lām d'un verbe, comme dans « qul naʿam » ?",["On le prononce toujours clairement","On le fond dans le nūn","On le cache","Ça dépend de la lettre"],0,"Vers 29 : « wa aẓhiranna lāma fiʿlin muṭlaqā », toujours clair, sauf devant un lām ou un rāʾ comme dans qul rabbi."),
(5,1,"Deux lettres identiques qui se suivent s'appellent…",["Mithlān","Mutaqāribān","Mutajānisān","Līn"],0,"Vers 30 : même point de sortie et mêmes caractéristiques, ce sont les « mithlān »."),
(5,2,"Même point de sortie, caractéristiques différentes :",["Mutajānisān","Mutaqāribān","Mithlān","Muttaṣil"],0,"Vers 32-33 : par exemple le dāl et le tāʾ dans ʿabadtum."),
(5,2,"Si la première des deux lettres est sans voyelle, l'idghām est…",["petit (ṣaghīr)","grand (kabīr)","interdit","lourd"],0,"Vers 33 : « faṣ-ṣaghīra sammiyan ». Si les deux ont une voyelle, c'est le grand idghām (vers 34)."),
(6,1,"Quelles sont les lettres du madd ?",["ا و ي","ن م ل","ء ه ع","ق ط ب"],0,"Vers 39 : elles sont réunies dans le mot « wāy »."),
(6,1,"Le madd naturel dure…",["2 temps","4 temps","6 temps","1 temps"],0,"Le madd naturel (ṭabīʿī) dure deux temps, sans hamza ni soukoun après la lettre de madd."),
(6,2,"Quelle voyelle doit précéder le yāʾ de madd ?",["La kasra","La fatḥa","La ḍamma","Le soukoun"],0,"Vers 40 : une kasra avant le yāʾ, une ḍamma avant le wāw, une fatḥa avant l'alif."),
(6,2,"Dans « yawm », le wāw est une lettre…",["de līn","de madd naturel","d'idghām","de ghunna"],0,"Vers 41 : wāw ou yāʾ sans voyelle, précédé d'une fatḥa : c'est une lettre de līn."),
(7,1,"Combien de règles a le madd ?",["3","2","4","5"],0,"Vers 42 : obligatoire (wujūb), permis (jawāz) et nécessaire (luzūm)."),
(7,1,"Dans « jāʾa », le madd est…",["obligatoire (muttaṣil)","séparé (munfaṣil)","naturel","ʿāriḍ"],0,"La hamza est dans le même mot que la lettre de madd : c'est le madd obligatoire attaché (vers 43)."),
(7,1,"Dans « innā anzalnāhu », le madd est…",["séparé (munfaṣil)","obligatoire (muttaṣil)","nécessaire","badal"],0,"La lettre de madd finit « innā » et la hamza commence le mot suivant : c'est le madd séparé (vers 44)."),
(7,2,"Dans « āmanū », la hamza vient avant le madd. C'est le madd…",["badal","ʿāriḍ","lāzim","muttaṣil"],0,"Vers 46 : « aw quddima l-hamzu ʿala l-maddi wa dhā badal », comme dans āmanū et īmānan."),
(7,1,"Combien de temps dure le madd lāzim ?",["6 temps","2 temps","4 temps","Au choix"],0,"Vers 47 : « baʿda maddin ṭuwwilā », il est allongé longuement, six temps."),
(8,1,"Combien de formes a le madd lāzim ?",["4","2","3","8"],0,"Vers 48-49 : kalimī ou ḥarfī, chacun léger ou lourd : quatre formes."),
(8,2,"Dans « aṭ-ṭāmmah », le madd lāzim est…",["kalimī lourd","kalimī léger","ḥarfī lourd","ḥarfī léger"],0,"Il est dans un mot (kalimī) et suivi d'une chadda, donc lourd (muthaqqal), vers 50 et 52."),
(8,1,"Quelle phrase réunit les huit lettres du madd lāzim ḥarfī ?",["Kam ʿasal naqaṣ","Ḥayyun ṭāhir","Yanmū","Ibghi ḥajjaka"],0,"Vers 54 : « kam ʿasal naqaṣ » (ك م ع س ل ن ق ص)."),
(8,2,"Les lettres de « ḥayyun ṭāhir » au début des sourates s'allongent…",["de 2 temps (madd naturel)","de 6 temps","de 4 temps","pas du tout"],0,"Vers 55-56 : leur nom n'a que deux lettres (ḥā, yā, ṭā, hā, rā), elles ont un madd naturel."),
(8,2,"Combien de vers compte le poème, selon le vers 59 ?",["61","40","100","1198"],0,"« Abyātuhū naddun badā » : en valeur des lettres, ن (50) + د (4) + ب (2) + د (4) + ا (1) = 61."),
]
